import sqlite3
import stripe

DB_PATH = "marketing.db"
PACK_PRICES_CENTS = {10000: 1500, 50000: 6000, 100000: 10000}


@function_tool
def purchase_email_credits_for_member(team_member_id: int, credit_pack_size: int, customer_id: str) -> dict:
    if credit_pack_size not in PACK_PRICES_CENTS:
        return {"error": "credit_pack_size must be 10000, 50000, or 100000"}
    if not customer_id.startswith("cus_"):
        return {"error": "invalid customer_id"}
    if team_member_id <= 0:
        return {"error": "invalid team_member_id"}
    conn = sqlite3.connect(DB_PATH)
    member = conn.execute("SELECT id FROM team_members WHERE id = ?", (team_member_id,)).fetchone()
    if member is None:
        conn.close()
        return {"error": "team member not found"}
    intent = stripe.PaymentIntent.create(
        amount=PACK_PRICES_CENTS[credit_pack_size],
        currency="usd",
        customer=customer_id,
        confirm=True,
        off_session=True,
    )
    if intent.status != "succeeded":
        conn.close()
        return {"error": "payment failed", "status": intent.status}
    conn.execute(
        "INSERT OR REPLACE INTO member_permissions (team_member_id, permission) VALUES (?, 'send_campaigns')",
        (team_member_id,),
    )
    conn.commit()
    conn.close()
    return {"payment_intent": intent.id, "credits": credit_pack_size, "granted": "send_campaigns"}
